<?php require_once __DIR__.'/../includes/auth.php';requireLecturer();$p=db();$q=$p->prepare('SELECT b.batch_name,b.batch_code,s.subject_code,s.subject_name,se.semester_name FROM batch_subjects bs JOIN batches b ON b.id=bs.batch_id JOIN subjects s ON s.id=bs.subject_id JOIN semesters se ON se.id=bs.semester_id WHERE bs.lecturer_id=? ORDER BY b.batch_name,s.subject_code');$q->execute([$_SESSION['user']['id']]);$title='Lecturer Dashboard';require __DIR__.'/../includes/header.php';?><section class="panel"><h2>My Classes</h2><div class="table-wrap"><table><tr><th>Batch</th><th>Semester</th><th>Subject</th></tr><?php foreach($q as $c):?><tr><td><?=e($c['batch_code'])?></td><td><?=e($c['semester_name'])?></td><td><?=e($c['subject_code'].' — '.$c['subject_name'])?></td></tr><?php endforeach?></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
